INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6d104cb8525f63902449','AMEDEX 2025 Pharmacology 1-33.pdf','133','Pharmacology','A 72-year-old woman presents to the
Emergency Department complaining of nausea
and vomiting. Apparently, she visited the on-call
GP a few days earlier and was prescribed
clarithromycin for a respiratory tract infection.
Past medical history of significance includes
chronic obstructive pulmonary disease (COPD)
for which she takes high-dose oral
corticosteroid, tiotropium and oral theophylline,
ischemic heart disease for which she takes
ramipril, amlodipine and indapamide, and
chronic kidney disease. On examination, she
has a blood pressure of 135/70 mmHg and
heart rate of 105 bpm that is irregularly irregular.
There is also bilateral basal lung crackles
consistent with mild left ventricular failure.
Her laboratory results are as follows:
¢ Hemoglobin: 11.4 mg/dl (11.5-16.5)
e WBC: 7 x 109/L (4x109 — 11x109)
e Platelet: 197 x 109/L(150x109 — 400x109)
e Serum sodium: 128 mmol/L (135 - 46)
e Serum potassium: 4.0 mmol/L (3.5 — 5)
e Creatinine: 178 umol/L (79 — 118 umol/L)
Which one of the following medication is most
likely to have resulted in her presentation?',NULL,NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Pharmacology 1-33.pdf","supporting_pages":[133],"source_qid":null,"duplicate_group_id":"exact-8ff37e0ec6c6","duplicate_sources":[{"record_id":"6d104cb8525f63902449","record_type":"visual_mcq","source_file":"AMEDEX 2025 Pharmacology 1-33.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Pharmacology 1-33.pdf","source_page":133,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/AMEDEX_2025_Pharmacology_1-33__f7c9a93f6cc8/page_00133.jpg","asset_preview_url":"https://drive.google.com/file/d/1X8ub79uA_pVdT-KLDlIzwSvnJ3F6MoMs/preview"}','visual_assets/AMEDEX_2025_Pharmacology_1-33__f7c9a93f6cc8/page_00133.jpg','https://drive.google.com/thumbnail?id=1X8ub79uA_pVdT-KLDlIzwSvnJ3F6MoMs&sz=w1600','source_page_image',NULL,'needs_verification','[]','medium','{"record_id":"6d104cb8525f63902449","record_type":"visual_mcq","source_file":"AMEDEX 2025 Pharmacology 1-33.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Pharmacology 1-33.pdf","source_year":2025,"source_page":133,"supporting_pages":[133],"source_qid":null,"domain_hint":"Pharmacology","stem":"A 72-year-old woman presents to the\nEmergency Department complaining of nausea\nand vomiting. Apparently, she visited the on-call\nGP a few days earlier and was prescribed\nclarithromycin for a respiratory tract infection.\nPast medical history of significance includes\nchronic obstructive pulmonary disease (COPD)\nfor which she takes high-dose oral\ncorticosteroid, tiotropium and oral theophylline,\nischemic heart disease for which she takes\nramipril, amlodipine and indapamide, and\nchronic kidney disease. On examination, she\nhas a blood pressure of 135/70 mmHg and\nheart rate of 105 bpm that is irregularly irregular.\nThere