INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d8a8c3af466d3f6e4666','AMEDEX 2025 Psychiatry  (1).pdf','20','Mental Health','A 27-year-old woman is being assessed in
your general practice after her marriage was
broken eight weeks ago. One year ago, she
was referred for psychotherapy from work
due to frequent conflicts with colleagues and
being easily irritated and shouting at them.
She complains that after finishing work, she
