INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('0888aea1e92d28a08165','AMEDEX 2025 Psychiatry  (1).pdf','50','Mental Health','Of the given options, asking the police about him is
the highest priority as it can provide additional
information for further management.
Once it is determined that the patient does not
have an acute medical problem, there are several
important questions, the answers to which will
guide the next step in managing the patient.
The first question is whether the patient has
delirium. It is not uncommon for a patient to go
through initial screening and have a diagnosis of
delirium overlooked. The patient may be
mistakenly diagnosed as being psychotic, or the
signs and symptoms of delirium may be subtle and
easily overlooked. In delirium, the patient has an
altered level of awareness and problems directing,
focusing, sustaining, or shifting attention. The
examiner must pay close attention to how the
patient interacts during the encounter and
recognize these often subtle signs. Does the
patient seem confused and unable to focus? Are
there perseverative behaviours? Does the patient
appear to be responding to visual hallucinations?
Are there signs of language impairment, problems
naming, or other cognitive deficits?',NULL,NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (1).pdf","supporting_pages":[50],"source_qid":null,"duplicate_group_id":"exact-b357f546425f","duplicate_sources":[{"record_id":"0888aea1e92d28a08165","record_type":"visual_mcq","source_file":"AMEDEX 2025 Psychiatry  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (1).pdf","source_page":50,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/AMEDEX_2025_Psychiatry_1__e2378124ec44/page_00050.jpg","asset_preview_url":"https://drive.google.com/file/d/193T5slzllvoGmTtoaSTNL6N_bt_mioMB/preview"}','visual_assets/AMEDEX_2025_Psychiatry_1__e2378124ec44/page_00050.jpg','https://drive.google.com/thumbnail?id=193T5slzllvoGmTtoaSTNL6N_bt_mioMB&sz=w1600','source_page_image',NULL,'needs_verification','[]','high','{"record_id":"0888aea1e92d28a08165","record_type":"visual_mcq","source_file":"AMEDEX 2025 Psychiatry  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (1).pdf","source_year":2025,"source_page":50,"supporting_pages":[50],"source_qid":null,"domain_hint":"Mental Health","stem":"Of the given options, asking the police about him is\nthe highest priority as it can provide additional\ninformation for further management.\nOnce it is determined that the patient does not\nhave an acute medical problem, there are several\nimportant questions, the answers to which will\nguide the next step in managing the patient.\nThe first question is whether the patient has\ndelirium. It is not uncommon for a patient to go\nthrough initial screening and have a diagnosis of\ndelirium overlooked. The patient may be\nmistakenly diagnosed as being psychotic, or the\nsigns and symptoms of delirium may be subtle and\neasily overlooked. In delirium, the patient has an\naltered level of awareness and problems directing,\nfocusing, sustaining, or shifting attention. The\nexaminer must pay close attention to how the\npatient interacts during the encounter and\nrecognize these often subtle signs. Does the\npatient seem confused and unable to focus? Are\nthere perseverative behaviours? Does the patient\nappear to be responding to visual hallucinations?\nAre there signs of language impairment, problems\nnaming, or other cognitive deficits?","options":null,"options_mode":"source_page_image","visual_asset":"visual_assets/AMEDEX_2025_Psychiatry_1__e2378124ec44/page_00050.jpg","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","screen","screening"],"likely_visual_question":true,"parser_confidence":"medium","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","stem_hash":"b357f546425f82f56b27a63ce9f6a835d3ff1bd8","duplicate_group_id":"exact-b357f546425f","duplicate_sources":[{"record_id":"0888aea1e92d28a08165","record_type":"visual_mcq","source_file":"AMEDEX 2025 Psychiatry  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (1).pdf","source_page":50,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,cu