INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('21256bbd007a5e7a07c0','AMEDEX 2025 Psychiatry  (1).pdf','60','Mental Health','A 20-year-old girl presents with a history of
episodes of trembling, palpitation, shortness
of breath, and sweating. Each episode lasts
for 5 minutes and then gradually resolves.
She has no history of heart disease and is not
on any regular medication. She denies any
use of illicit drugs. Which one of the following
