INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8e57964cfef9226df6fe','AMEDEX 2025 Psychiatry  (1).pdf','84','Mental Health','Bradley, 47 years old, is being assessed for
multiple issues. He has been suffering from
arthritic joint pain for the past 2 years and Is
under treatment for that. He lost his job as a
local manager eight months ago due to his
health issues and receives a pension from
Centrelink. He has withdrawn from his social
activities and cancelled his local club
membership. He wakes up very early in the
morning and finds it difficult to sleep again. His
appetite is not good, and he has lost 8
kilograms in the past 4 months. During the
consultation, he speaks with a low, monotonous
voice and avoids eye contact. When questioned
if he was seeking a job, he answers and only
gives short answers to your questions. He has
a negative outlook towards several issues. For
instance, when asked if he is seeking a job, he
says: “Oh. It is very difficult to find a job these
days’, or “| am not adjusting well’. Based on the
history and findings, which of the following is
more likely to be the diagnosis?','{"A":"Adjustment Disorder.","B":"Major Depressive Disorder.","C":"Schizophrenia.","D":"Anxiety Disorder.","E":"Dysthymia."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (1).pdf","supporting_pages":[84,85],"source_qid":null,"duplicate_group_id":"exact-e1b25c9614be","duplicate_sources":[{"record_id":"8e57964cfef9226df6fe","record_type":"text_mcq","source_file":"AMEDEX 2025 Psychiatry  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (1).pdf","source_page":84,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"8e57964cfef9226df6fe","source_file":"AMEDEX 2025 Psychiatry  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (1).pdf","source_year":2025,"source_page":84,"supporting_pages":[84,85],"source_qid":null,"domain_hint":"Mental Health","stem":"Bradley, 47 years old, is being assessed for\nmultiple issues. He has been suffering from\narthritic joint pain for the past 2 years and Is\nunder treatment for that. He lost his job as a\nlocal manager eight months ago due to his\nhealth issues and receives a pension from\nCentrelink. He has withdrawn from his social\nactivities and cancelled his local club\nmembership. He wakes up very early in the\nmorning and finds it difficult to sleep again. His\nappetite is not good, and he has lost 8\nkilograms in the past 4 months. During the\nconsultation, he speaks with a low, monotonous\nvoice and avoids eye contact. When questioned\nif he was seeking a job, he answers and only\ngives short answers to your questions. He has\na negative outlook towards several issues. For\ninstance, when asked if he is seeking a job, he\nsays: “Oh. It is very difficult to find a job these\ndays’