INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d90f910483ed830cea24','AMEDEX 2025 Psychiatry  (1).pdf','100','Mental Health','A 17-year-old boy is brought to your office by
his mother for evaluation. History reveals that
he had been a good student until age 15
when his grades began dropping. His mother
has also noticed that he has stopped
socialising with friends and started spending
more time alone in his room. He dropped out
of school earlier this year due to poor school
performance. His mother reports that he has
been trying to home-school him, but he does
not seem interested in learning. Days go
before he takes a bath, and he does not seem
to care about his appearance. What concerns
the mother most and has led her to bring him
to see a psychiatrist is the fact that for the
past two months, she has overheard him
having what sounds like conversations with
someone imaginary in his room. Which one of
the following could be the most likely
diagnosis?','{"A":"Major depressive disorder.","B":"Substance abuse disorder.","C":"Schizophrenia.","D":"Brief psychotic disorder.","E":"Schizophreniform disorder."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (1).pdf","supporting_pages":[100,101],"source_qid":null,"duplicate_group_id":"exact-3d3c3ed6d3b6","duplicate_sources":[{"record_id":"d90f910483ed830cea24","record_type":"text_mcq","source_file":"AMEDEX 2025 Psychiatry  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (1).pdf","source_page":100,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"d90f910483ed830cea24","source_file":"AMEDEX 2025 Psychiatry  (1).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (1).pdf","source_year":2025,"source_page":100,"supporting_pages":[100,101],"source_qid":null,"domain_hint":"Mental Health","stem":"A 17-year-old boy is brought to your office by\nhis mother for evaluation. History reveals that\nhe had been a good student until age 15\nwhen his grades began dropping. His mother\nhas also noticed that he has stopped\nsocialising with friends and started spending\nmore time alone in his room. He dropped out\nof school earlier this year due to poor school\nperformance. His mother reports that he has\nbeen trying to home-school him, but he does\nnot seem interested in learning. Days go\nbefore he takes a bath, and he does not seem\nto care about his appearance. What concerns\nthe mother most and has led her to bring him\nto see a psychiatrist is the fact that for the\npast two months, she has overheard him\nhaving what sounds like conversations with\nsomeone imaginary in his room. Which one of\nthe following could be the most likely\ndiagnosis?","options":{"A"