INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('dbe1c6846111277e4c90','AMEDEX 2025 Psychiatry  (1).pdf','153','Mental Health','A 75-year-old woman is brought to your
practice by her husband, who complains that
She is not herself anymore. The problem
Started with reduced self-care and, episodic
disorientation and forgetfulness. She refuses
to bathe and barely changes her clothes.
Recently, she has developed difficulty walking
and has had several falls. Last night, she
Started yelling and screaming because she
thought snakes were slithering on the floor.
On examination, she is dishevelled and
disoriented to time, place, and person. Fine
resting tremors of her hands, mostly
prominent on the right, are noted. When
asked to walk, she has difficulty starting and
