INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4bf7593adcd9376b7b0d','AMEDEX 2025 Psychiatry  (3).pdf','1','Mental Health','Victoria is in your office for a consultation. She
is 33 and gave birth to her first son six weeks
ago. She Is grateful for having him and spends
most of her time with him. However, she feels
tired because she cannot sleep enough at night
and needs to wake up several times to feed
him. Victoria’s husband supports her
emotionally but cannot be of much help
because his job requires him to work long hours
outside. She needs help with her situation,
specifically about her sleep and tiredness.
Which of the following is the most appropriate
management option at this stage?','{"A":"Prescribe a short course of\ntemazepam to help her sleep.","B":"Arrange for nursing assistance at\nhome.","C":"Start her on low-dose SSRI.","D":"Refer her to a psychologist.","E":"Refer for family counseling and\ntherapy."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (3).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-5273114a2249","duplicate_sources":[{"record_id":"4bf7593adcd9376b7b0d","record_type":"text_mcq","source_file":"AMEDEX 2025 Psychiatry  (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (3).pdf","source_page":1,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"4bf7593adcd9376b7b0d","source_file":"AMEDEX 2025 Psychiatry  (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (3).pdf","source_year":2025,"source_page":1,"source_qid":null,"domain_hint":"Mental Health","stem":"Victoria is in your office for a consultation. She\nis 33 and gave birth to her first son six weeks\nago. She Is grateful for having him and spends\nmost of her time with him. However, she feels\ntired because she cannot sleep enough at night\nand needs to wake up several times to feed\nhim. Victoria’s husband supports her\nemotionally but cannot be of much help\nbecause his job requires him to work long hours\noutside. She needs help with her situation,\nspecifically about her sleep and tiredness.\nWhich of the following is the most appropriate\nmanagement option at this stage?","options":{"A":"Prescribe a short course of\ntemazepam to help her sleep.","B":"Arrange for nursing assistance at\nhome.","C":"Start her on low-dose SSRI.","D":"Refer her to a psychologist.","E":"Refer for family counseling and\ntherap