INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('31a6b19a2bf73fa6a2d0','AMEDEX 2025 Psychiatry  (3).pdf','100','Mental Health','Conventional support (e.g., family, social, religious,
social) is usually sufficient to help the patient with
grief. Although there is often little place for
pharmacotherapy, anxiolytics and hypnotics can
provide prompt relief where indicated due to
excessive insomnia and anxiety. A short course of
benzodiazepines (< 7 days) can be used to help
with insomnia and anxiety.
The patient has no psychotic features
necessitating antipsychotics such as olanzapine
(option C). Antidepressants such as venlafaxine
(option A) and citalopram (option E) might be
indicated in patients with complicated grief or grief
associated with major depression, none of which is
the case here.
ECT (option B) might very infrequently be
indicated in selected patients with complicated
grief reactions.
Reference(s) +° UpToDate - Bereavement and gri
ef in adults: Clinical features
¢ Medscape - What are the DSM-5
criteria for diagnosis of major depr
essive disorder (clinical depressio
