INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('933add3c9e4cd11ecfe0','AMEDEX 2025 Psychiatry  (3).pdf','101','Mental Health','A 17-year-old girl is diagnosed with major
depression associated with psychotic
features. She is planned to be started on
