INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d4f39bae587e6e159723','AMEDEX 2025 Psychiatry  (3).pdf','121','Mental Health','Aida is a pregnant patient who presented for
an antenatal visit in her first trimester. This is
her second pregnancy. Her previous
pregnancy, three years ago, was followed by
the development of postpartum psychosis,
for which she was successfully treated with
risperidone. The medication was then
tapered and stopped. She has been stable
since. She wants to know if there is anything
she can do to prevent postpartum psychosis
in this pregnancy. Which one of the following
would be the most appropriate advice?','{"A":"Review her later in pregnancy.","B":"Start prophylactic dose of\nantidepressants.","C":"Start her on antipsychotics now.","D":"Start her on risperidone if she\ndevelops postpartum psychosis\nagain.","E":"Start risperidone immediately after\ndelivery."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (3).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-4d6fe7bae370","duplicate_sources":[{"record_id":"d4f39bae587e6e159723","record_type":"text_mcq","source_file":"AMEDEX 2025 Psychiatry  (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (3).pdf","source_page":121,"source_qid":null},{"record_id":"0008d330d888e386e3f8","record_type":"text_mcq","source_file":"Psychiatry  Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Psychiatry  Amedex 2025.pdf","source_page":131,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"d4f39bae587e6e159723","source_file":"AMEDEX 2025 Psychiatry  (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (3).pdf","source_year":2025,"source_page":121,"source_qid":null,"domain_hint":"Mental Health","stem":"Aida is a pregnant patient who presented for\nan antenatal visit in her first trimester. This is\nher second pregnancy. Her previous\npregnancy, three years ago, was followed by\nthe development of postpartum psychosis,\nfor which she was successfully treated with\nrisperidone. The medication was then\ntapered and stopped. She has been stable\nsince. She wants to know if there is anything\nshe can do to prevent postpartum psychosis\nin this pregnancy. Which one of the following\nwould be the most appropriate advice?","options":{"A":"Review her later in pregnancy.","B":"Start prophylactic dose of\nantidepressants.","C":"Start her on antipsychotics now.","D":"Start her on risperidone if she\ndevelops postpartum psychosis\nagain.","E":"Start risperidone immediately after\ndelivery."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","stem_hash":"4d6fe7bae37030e49769d40eeb1d9a177c44700d","duplicate_group_id":"exact-4d6fe7bae370","duplicate_sources":[{"record_id":"d4f39bae587e6e159723","record_type":"text_mcq","source_file":"AMEDEX 2025 Psychiatry  (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry  (3).pdf","source_page":121,"source_qid":null},{"record_id":"0008d330d888e386e3f8","record_type":"text_mcq","source_file":"Psychiatry  Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Psychiatry  Amedex 2025.pdf","source_page":131,"source_qid":null}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_qu